var own=['settings','settings--sign-out','artifacts--code','projects--new','routines--new','settings-billing--plan','artifacts--share'];doc.pages.filter(p=>['Proto iOS Light','Proto iOS Dark'].includes(p.name)).forEach(p=>p.layers.filter(s=>s.name.startsWith('Screen/ios/')&&own.includes(s.name.split('/').pop())).forEach(s=>{var b=s.layers.find(l=>l.name==='body'),t=s.layers.find(l=>l.name==='tab-bar'),sh=s.layers.find(l=>l.name==='sheet');console.log(JSON.stringify({name:s.name,id:String(s.id),w:s.frame.width,h:s.frame.height,bodyY:b.frame.y,bodyBottom:Math.max.apply(null,b.layers.map(l=>l.frame.y+l.frame.height))+b.frame.y,tabY:t?t.frame.y:null,sheet:sh?sh.layers.map(l=>({name:l.name,y:l.frame.y,h:l.frame.height})):null}));}));